//! PE32+ (AArch64) loader and minimal WinAPI translation.
//!
//! KimiOS does not implement Windows. Instead, the import table of a PE image
//! is resolved against a small table of translated functions. Each import is
//! pointed at a generated EL0 thunk that turns the Windows-style call into a
//! KimiOS `svc`. Only a handful of `kernel32.dll` entry points are supported:
//! `GetStdHandle`, `WriteFile`, `ExitProcess`, `GetLastError` and
//! `SetLastError`.
//!
//! The test image is generated by `build.rs`, because there is no Windows
//! ARM64 toolchain in this project.

use core::arch::asm;

use crate::{mmu, pfa, println};

const PAGE_SIZE: u64 = 4096;

/// User-virtual address of the generated import thunk page.
pub const THUNK_VA: u64 = 0x6300_0000;
/// User stack for PE processes.
const PE_STACK_VA: u64 = 0x6400_0000;

pub const SYS_PE_GET_STD_HANDLE: u64 = 100;
pub const SYS_PE_WRITE_FILE: u64 = 101;
pub const SYS_PE_EXIT_PROCESS: u64 = 102;
pub const SYS_PE_GET_LAST_ERROR: u64 = 103;
pub const SYS_PE_SET_LAST_ERROR: u64 = 104;

pub struct LoadedImage {
    pub entry: u64,
    pub stack_top: u64,
}

#[derive(Clone, Copy, Default)]
struct Section {
    virtual_address: u32,
    raw_size: u32,
    raw_pointer: u32,
    executable: bool,
}

fn read_u16(image: &[u8], offset: usize) -> Option<u16> {
    let bytes = image.get(offset..offset + 2)?;
    Some(u16::from_le_bytes([bytes[0], bytes[1]]))
}

fn read_u32(image: &[u8], offset: usize) -> Option<u32> {
    let bytes = image.get(offset..offset + 4)?;
    Some(u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]))
}

fn read_u64(image: &[u8], offset: usize) -> Option<u64> {
    let bytes = image.get(offset..offset + 8)?;
    Some(u64::from_le_bytes([
        bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6],
        bytes[7],
    ]))
}

fn read_cstr(image: &[u8], offset: usize) -> Option<&str> {
    let tail = image.get(offset..)?;
    let length = tail.iter().position(|&byte| byte == 0)?;
    core::str::from_utf8(&tail[..length]).ok()
}

fn rva_to_offset(sections: &[Section], rva: u32) -> Option<usize> {
    for section in sections {
        if rva >= section.virtual_address
            && rva < section.virtual_address + section.raw_size
        {
            return Some((section.raw_pointer + (rva - section.virtual_address)) as usize);
        }
    }
    None
}

fn thunk_id(name: &str) -> Option<u64> {
    match name {
        "GetStdHandle" => Some(SYS_PE_GET_STD_HANDLE),
        "WriteFile" => Some(SYS_PE_WRITE_FILE),
        "ExitProcess" => Some(SYS_PE_EXIT_PROCESS),
        "GetLastError" => Some(SYS_PE_GET_LAST_ERROR),
        "SetLastError" => Some(SYS_PE_SET_LAST_ERROR),
        _ => None,
    }
}

fn thunk_address(id: u64) -> u64 {
    THUNK_VA + (id - SYS_PE_GET_STD_HANDLE) * 16
}

fn encode_movz(register: u32, immediate: u16) -> u32 {
    0xd280_0000 | ((immediate as u32) << 5) | register
}

fn encode_svc() -> u32 {
    0xd400_0001
}

fn encode_ret() -> u32 {
    0xd65f_03c0
}

fn encode_nop() -> u32 {
    0xd503_201f
}

/// Build one page of `mov x8, #id; svc #0; ret; nop` thunks.
fn build_thunks(frame: u64, count: u64) {
    for slot in 0..count {
        let id = SYS_PE_GET_STD_HANDLE + slot;
        let destination = (frame + slot * 16) as *mut u32;
        let words = [
            encode_movz(8, id as u16),
            encode_svc(),
            encode_ret(),
            encode_nop(),
        ];
        unsafe {
            for (index, word) in words.iter().enumerate() {
                core::ptr::write_volatile(destination.add(index), *word);
            }
        }
    }

    unsafe {
        asm!("dsb ish", "ic ialluis", "dsb ish", "isb");
    }
}

pub fn is_pe(image: &[u8]) -> bool {
    image.len() >= 0x40 && &image[..2] == b"MZ"
}

pub fn load(image: &[u8]) -> Result<LoadedImage, &'static str> {
    if !is_pe(image) {
        return Err("missing MZ header");
    }

    let pe_offset = read_u32(image, 0x3c).ok_or("truncated DOS header")? as usize;
    if image.get(pe_offset..pe_offset + 4) != Some(b"PE\0\0") {
        return Err("missing PE signature");
    }

    let coff = pe_offset + 4;
    let machine = read_u16(image, coff).ok_or("truncated COFF header")?;
    if machine != 0xaa64 {
        return Err("PE is not AArch64");
    }

    let section_count = read_u16(image, coff + 2).ok_or("truncated COFF header")? as usize;
    if section_count == 0 || section_count > 16 {
        return Err("unsupported section count");
    }
    let optional_size = read_u16(image, coff + 16).ok_or("truncated COFF header")? as usize;

    let optional = coff + 20;
    let magic = read_u16(image, optional).ok_or("truncated optional header")?;
    if magic != 0x20b {
        return Err("PE is not PE32+");
    }

    let entry_rva = read_u32(image, optional + 16).ok_or("truncated optional header")?;
    let image_base = read_u64(image, optional + 24).ok_or("truncated optional header")?;
    let image_size = read_u32(image, optional + 56).ok_or("truncated optional header")?;
    let directory_count =
        read_u32(image, optional + 108).ok_or("truncated optional header")?;

    if image_base < 0x4000_0000
        || image_base >= 0x8000_0000
        || image_base + image_size as u64 > THUNK_VA
    {
        return Err("unsupported image base");
    }

    let table = optional + optional_size;
    let mut sections = [Section::default(); 16];
    let mut pages = 0;

    for index in 0..section_count {
        let header = table + index * 40;
        let virtual_size = read_u32(image, header + 8).ok_or("truncated section table")?;
        let virtual_address = read_u32(image, header + 12).ok_or("truncated section table")?;
        let raw_size = read_u32(image, header + 16).ok_or("truncated section table")?;
        let raw_pointer = read_u32(image, header + 20).ok_or("truncated section table")?;
        let characteristics =
            read_u32(image, header + 36).ok_or("truncated section table")?;

        if raw_pointer as usize + raw_size as usize > image.len() {
            return Err("section extends past end of file");
        }

        let section = Section {
            virtual_address,
            raw_size,
            raw_pointer,
            executable: characteristics & 0x2000_0000 != 0,
        };
        sections[index] = section;

        if virtual_size == 0 {
            continue;
        }

        println!(
            "  PE section va={:#010x} vsize={} raw={} {}",
            image_base + virtual_address as u64,
            virtual_size,
            raw_size,
            if section.executable { "X" } else { "R" }
        );

        let first_page = (image_base + virtual_address as u64) & !(PAGE_SIZE - 1);
        let end = image_base + virtual_address as u64 + virtual_size as u64;
        let last_page = (end + PAGE_SIZE - 1) & !(PAGE_SIZE - 1);

        let mut page = first_page;
        while page < last_page {
            let frame = pfa::alloc_frame().ok_or("out of physical memory")?;
            unsafe {
                core::ptr::write_bytes(frame as *mut u8, 0, PAGE_SIZE as usize);
            }

            let copy_start = page.max(image_base + virtual_address as u64);
            let copy_end = (page + PAGE_SIZE)
                .min(image_base + virtual_address as u64 + raw_size as u64);
            if copy_start < copy_end {
                let source = raw_pointer as usize
                    + (copy_start - (image_base + virtual_address as u64)) as usize;
                let destination = (frame + (copy_start - page)) as *mut u8;
                let count = (copy_end - copy_start) as usize;
                unsafe {
                    core::ptr::copy_nonoverlapping(
                        image.as_ptr().add(source),
                        destination,
                        count,
                    );
                }
            }

            mmu::map_user_page(page, frame, section.executable);
            pages += 1;
            page += PAGE_SIZE;
        }
    }

    // Import table: resolve names to thunks and patch each IAT slot.
    let mut imports = 0;
    if directory_count > 1 {
        let import_rva = read_u32(image, optional + 112 + 8).unwrap_or(0);
        let import_size = read_u32(image, optional + 112 + 12).unwrap_or(0);

        if import_rva != 0 && import_size != 0 {
            let mut descriptor =
                rva_to_offset(&sections, import_rva).ok_or("bad import directory")?;

            for _ in 0..32 {
                let original_first_thunk =
                    read_u32(image, descriptor).ok_or("truncated import descriptor")?;
                let name_rva =
                    read_u32(image, descriptor + 12).ok_or("truncated import descriptor")?;
                let first_thunk =
                    read_u32(image, descriptor + 16).ok_or("truncated import descriptor")?;

                if original_first_thunk == 0 && name_rva == 0 && first_thunk == 0 {
                    break;
                }

                let lookup_rva = if original_first_thunk != 0 {
                    original_first_thunk
                } else {
                    first_thunk
                };
                let lookup =
                    rva_to_offset(&sections, lookup_rva).ok_or("bad import lookup table")?;
                let dll = read_cstr(
                    image,
                    rva_to_offset(&sections, name_rva).ok_or("bad import DLL name")?,
                )
                .unwrap_or("?");
                let mut index = 0;

                loop {
                    let entry =
                        read_u64(image, lookup + index * 8).ok_or("truncated import table")?;
                    if entry == 0 {
                        break;
                    }
                    if entry & (1 << 63) != 0 {
                        return Err("ordinal imports are not supported");
                    }

                    let hint_name = rva_to_offset(&sections, entry as u32)
                        .ok_or("bad import name RVA")?;
                    let name = read_cstr(image, hint_name + 2).ok_or("bad import name")?;
                    let id = thunk_id(name).ok_or("unsupported import")?;

                    let slot = image_base + first_thunk as u64 + index as u64 * 8;
                    unsafe {
                        core::ptr::write_volatile(slot as *mut u64, thunk_address(id));
                    }

                    println!("  import {}!{}", dll, name);
                    imports += 1;
                    index += 1;
                }

                descriptor += 20;
            }
        }
    }

    // Thunk page (EL0 executable) and stack page.
    let thunk_frame = pfa::alloc_frame().ok_or("out of memory for PE thunks")?;
    unsafe {
        core::ptr::write_bytes(thunk_frame as *mut u8, 0, PAGE_SIZE as usize);
    }
    build_thunks(thunk_frame, 5);
    mmu::map_user_page(THUNK_VA, thunk_frame, true);
    pages += 1;

    let stack_frame = pfa::alloc_frame().ok_or("out of memory for PE stack")?;
    unsafe {
        core::ptr::write_bytes(stack_frame as *mut u8, 0, PAGE_SIZE as usize);
    }
    mmu::map_user_page(PE_STACK_VA, stack_frame, false);
    pages += 1;

    let entry = image_base + entry_rva as u64;
    println!(
        "PE loaded  : base={:#x} entry={:#x} pages={} imports={}",
        image_base, entry, pages, imports
    );

    Ok(LoadedImage {
        entry,
        stack_top: PE_STACK_VA + PAGE_SIZE,
    })
}
